/* ===== Gear Library: every line on the sheet ===== */
(function(){
var S='https'+':'+'//';
var PH={"avantis":"","msub18":"","m1220":"","lens":"","bmdda":"","radial":"","rapco":"","cs702":"","rs601":"","ulxd1":"","ulxd4":"","sm58":"","wl185":""};
var GEAR=[["vid","13' x 23' Dual Absen LED Screen System, Hanging","1 system","","Two LED screens flown side by side. 112 tiles split into <b>2 screens of 56 tiles (7 wide × 8 tall) = 2688×1536 px each</b>. One MX40 PRO per screen feeds them. <b>If part of a screen is dark:</b> find the first dead tile; everything downstream of it on that data run loses signal, everything upstream stays lit.",[["Absen SA2.6 spec sheet","cdn01.4wall.com/cms/rentals/files/f69654d29be40a.pdf"]],"v"],["vid","Absen Saturn SA2.6mm LED Tile, 1000mm x 500mm","112","absen","2.6 mm pitch indoor LED tile, <b>1000 × 500 × 70 mm, 9.5 kg</b>, 384 × 192 px per tile. Power draw about 510 W/m² max, 270 W/m² typical. Handle by the frame, never press the face. Keep tile cases closed and on their ramps.",[["Absen SA2.6 spec sheet","cdn01.4wall.com/cms/rentals/files/f69654d29be40a.pdf"]],"v"],["vid","Novastar MX40 PRO 4k Processor","2","mx40","LED processor. Takes video in and splits it into data for the tiles over <b>20 gigabit Ethernet ports</b> (plus backup). Up to 9 million pixels, about 95 W. One per screen. <b>Screen dead but processor is on:</b> check the input signal first, then the first Ethernet link into the screen.",[["MX40 Pro spec","www.rentex.com/wp-content/uploads/2023/01/MX40-Pro-LED-Display-Controller-Specification.pdf"],["MX40 Pro manual","www.rentex.com/wp-content/uploads/2023/01/MX40-Pro-LED-Display-Controller-User-Manual-V.pdf"]],"v"],["vid","Pixelhue P20-DS Presentation Switcher and Screen Management","1","p20","Presentation switcher and screen manager. <b>12 inputs (4× 12G-SDI, 8× DP/HDMI), 12 layers</b>, a dedicated multiviewer output. The <b>DS</b> adds four 12G-SDI outputs and Dante. The photo shows the P20; the DS is the same family. Routes sources to the two Absen screens and the 27\" multiview at FOH.",[["P20 / P20-DS spec","www.rentex.com/wp-content/uploads/2026/04/P20-P20-DS-Seamless-Switchers-Specifications-V1.7.1.pdf"]],"v"],["vid","Road Hog High End DMX Console","1","","Road Hog 4 lighting console: <b>22\" touchscreen, 4 onboard DMX outputs, Art-Net/sACN over one gigabit Ethernet port, 10 pageable playbacks, 4 wheels</b>, 5 USB ports. Runs the Maverick movers, Ovation ellipsoidals and WELL Panels. In the console's own manual, press <b>Help</b> on the right-hand screen toolbar.<br><b>No lights respond:</b> check universe, start address and mode on the fixture first, then the console's DMX/network output.",[["Road Hog 4 spec","cdn01.4wall.com/cms/rentals/files/f5bc608f4e0699.pdf"],["Hog 4 OS manual","www.etcconnect.com/webdocs/Controls/HOG/HTML/en/index.htm"],["Getting started chapter","www.etcconnect.com/webdocs/Controls/HOG/HTML/en/chap-getting_started.htm"]],"v"],["vid","Camera w/42x lens","side note","","A side note on the sheet, not a labelled line. Almost certainly a broadcast/studio camera with a 42× zoom lens for the screens. <b>Ask the production lead</b> which camera, what its output is (SDI?), and who operates it.",[],"c"],["vid","Dual Confidence Monitor Package","2","","Confidence monitors so presenters can see their slides without turning around. Production note: <b>put the DSM stands on road cases to lift them as high as possible</b> on the 4' riser. Keep cables clear of presenter paths.",[],"c"],["vid","50\" Sharp TV Display","4","","Sharp 50\" display used as a confidence monitor. The sheet doesn't give the model number. Fed over HDMI or SDI through a converter. <b>No picture:</b> input select on the TV, then the cable, then the converter's power. Brand and model are not on the sheet. General practice only; read the label on site.",[],"c"],["vid","Confidence Monitor Stand Medium DSM","4","","Stands for the confidence monitors. Per the production notes they go on road cases to lift them as high as possible. Weight the base, check the display clamp is tight, and keep the cable strain-relieved.",[],"c"],["vid","Video Converter Package","1","","The package holds the Blackmagic bidirectional converters and the 1×8 SDI distribution amp listed below. Use it to turn SDI to HDMI (or back) for TVs and monitors.",[],"v"],["vid","Black Magic Design BiDirectional SDI/HDMI 3G Converter","8","bmd","Converts SDI to HDMI <b>or</b> HDMI to SDI, up to 3G. The sheet doesn't say which version; the Micro type is <b>powered over USB (5 V)</b>, so a dead one is often a loose or underpowered USB lead. Check that the in/out are on the right connectors; an SDI-in and an HDMI-in used at once is a common mix-up.",[["Blackmagic converters manual","www.adorama.com/col/productManuals/BMMCSG.pdf"]],"v"],["vid","Black Magic SDI Distribution Unit, 1x8","1","bmdda","Blackmagic Mini Converter SDI Distribution: <b>1 SDI in, 8 re-clocked SDI out</b>, automatically matches SD, HD or 3G-SDI (up to 1080p60). Comes with a 12 V supply (12–30 V accepted). No switches. <b>An output is dead:</b> swap the cable or try another output; if every output is dead, check input and power.",[["Product page (Markertek)","www.markertek.com/product/bmd-convmsdida/blackmagic-design-convmsdida-mini-converter-1x8-3g-sdi-distribution-amplifier"]],"v"],["vid","Video Playback Package- Playback Pro","2","","Playback package: MacBook Pro 14\", PlaybackPro software and an audio DI. <b>Before doors:</b> screen saver and sleep off, volume full, media on a drive that isn't the system drive, and the USB enabler key plugged in.",[["PlaybackPro user guide (v2.2)","hire.on-productions.co.uk/uploads/docs/PlaybackPro_User_Guide.pdf"]],"v"],["vid","Playback Pro- Video Software","2","","PlaybackPro runs video clips from a Playlist. In the v2.2 guide: <b>Return = Take (play the loaded clip)</b>, <b>Esc = End All Playback</b>, Space = play/pause, ↑/↓ = previous/next clip. <b>Grey clip:</b> the file moved or is offline; use Relocate. <b>Watermark on output:</b> the USB enabler key is missing, so plug it in and reopen the show file. The guide covers v2.2, so check the version on your copy.",[["PlaybackPro user guide (v2.2)","hire.on-productions.co.uk/uploads/docs/PlaybackPro_User_Guide.pdf"]],"c"],["vid","MacBook Pro 14\"","2","","Playback computers. Turn off sleep, screen saver and notifications. A laptop needs an external output for the screens, so check the display adapter is plugged in and set to extended or mirrored as the video lead says.",[],"c"],["vid","HP 14\" EliteBook Laptop Notebook","3","","Windows laptops (presentation or backup). Set power plan to never sleep, plug into AC, and check HDMI output (Win+P) if a screen shows nothing.",[],"c"],["lx","Chauvet WELL Panel Wireless Event LED Luminaire","6","well","Battery-powered LED wash, <b>W-DMX wireless, IP65, 22.6 lb</b>. About 4 h to charge; run modes of 3, 5, 8 or 12 h. <b>Won't respond:</b> check W-DMX link and that it is on the right address/mode. <b>Dies early:</b> it wasn't fully charged or is in a bright run mode.",[["WELL Panel manual","www.chauvetprofessional.com/wp-content/uploads/2020/10/WELL_Panel_UM_Rev4.pdf"]],"v"],["lx","Chauvet Maverick MK1 Hybrid Light Fixture","4","maverick","Moving-head hybrid fixture with a <b>440 W Osram Sirius discharge lamp</b> (not LED): <b>5.45 A at 120 V, 66.7 lb</b>, 27 or 30 channel modes. Lamp needs to strike and warm up. <b>Won't strike:</b> give it time, check power, then the console's lamp control. Never move a hot lamp roughly.",[["Maverick MK1 Hybrid spec","chauvetprofessional.com/wp-content/uploads/pdf/en/MAVERICKMK1HYBRID.pdf"],["Product page","chauvetprofessional.com/product/maverick-mk1-hybrid/"]],"v"],["lx","Chauvet Ovation E-910FC Light Fixture","12","ovation","LED ellipsoidal (RGBAL) that takes Source Four-style lens tubes. About <b>220 W / 1.79 A at 120 V; max 6 per circuit; 19.8 lb with the 26° tube</b>. Fixture needs universe, start address and mode matched to the console. If alive but ignoring the console, it is almost always one of those three.",[["Ovation E-910FC manual","www.chauvetprofessional.com/wp-content/uploads/2015/09/Ovation_E-910FC_UM_Rev19.pdf"]],"v"],["lx","ETC Source Four Lens Tube, 26 Degree","12","lens","Spare 26° lens tube for Source Four-style ellipsoidals. The sheet says <b>12</b> in one place and <b>8</b> in a side note, so confirm. Swap tubes by loosening the tube, never touching the lens glass with bare hands.",[["Product listing","www.fullcompass.com/prod/081540-etc-sourcefour-lens-tube-26-degree-source-four-lens-tube"]],"c"],["lx","DSan AV1000 Speaker Timer","1","","Speaker timer / countdown clock. I couldn't verify a DSan 'AV1000' model online, so the exact buttons are unknown. A common timer is the D'San Limitimer, but <b>don't assume</b>; read the label and ask the stage manager how they want it set.",[],"c"],["aud","Nexo Geo Sound System","1 system","","The main PA: GEO M12 line array, MSUB18 subs, NXAMP 4x4 amps. Each GEO M12 box is <b>34 kg</b>; arrays up to <b>12 boxes</b> on the bumper. An NXAMP4x4 channel drives <b>3 M12 boxes</b>. Only hang from rated points with the 4½-ton shackles and spansets listed in Rig.",[["GEO M12 datasheet","www.nexo-sa.com/wp-content/uploads/GeoM12_datasheet_v1.2.pdf"]],"v"],["aud","Nexo Geo M1210 Line Array Speaker, 10º","12","m1210","12\" 2-way line array box with <b>10° vertical coverage</b>, 34 kg. Four NL4 connections. Check array order and angles with the A1 before flying. <b>Box dead:</b> check the NL4 link and the amp channel before opening anything.",[["GEO M12 datasheet","www.nexo-sa.com/wp-content/uploads/GeoM12_datasheet_v1.2.pdf"],["M1210 page","www.nexo-sa.com/products/geo-m1210/"]],"v"],["aud","Nexo Geo M1220 Line Array Speaker, 20º","2","m1220","Same cabinet family as the M1210 but <b>20° vertical coverage</b> — wider, used at the bottom of an array for the closest seats. Same rigging and NL4 wiring.",[["M1220 page","www.nexo-sa.com/products/geo-m1220"]],"v"],["aud","Nexo Geo M12 Light Bumper, 12 Box Array","2","","The flying frame the array hangs from, rated for a <b>12-box</b> M12 array per the sheet. Never exceed the rated count. Get the exact rigging load info from Nexo's datasheet and the rigger in charge.",[["GEO M12 datasheet","www.nexo-sa.com/wp-content/uploads/GeoM12_datasheet_v1.2.pdf"]],"c"],["aud","Nexo Extension Bar for Geo M12 Line Array Bumper","2","","Extension bar that attaches to the bumper to change the array's hang point/angle. The sheet gives no model details; follow the rigger's instructions and the Nexo datasheet for pin orientation.",[["GEO M12 datasheet","www.nexo-sa.com/wp-content/uploads/GeoM12_datasheet_v1.2.pdf"]],"c"],["aud","Nexo Geo MSUB18 Arrayable Subwoofer","6","msub18","Compact 18\" subwoofer: <b>55 kg (122 lb)</b>, 4 ohm, <b>four NL4 connectors</b> (1± feed it, 2± pass through). Runs <b>omni or cardioid</b> (cardioid uses front and rear boxes wired front-to-back). Recommended <b>2 per NXAMP4x4 channel</b>. 8 side handles — use a team lift.",[["MSUB18 page","www.nexo-sa.com/products/msub18/"]],"v"],["aud","Nexo NXAMP 4x4 Channel Amp & Processing","3","","4-channel amplifier with built-in processing (the speaker presets live here). Drives <b>3 M12 boxes per channel</b> or 2 MSUB18 per channel. <b>No sound from one set of boxes:</b> check the NL4 to that channel, then the amp channel's mute and preset.",[["NXAMP4x4 datasheet","nexo-sa.com/wp-content/uploads/nxamp4x4_datasheet_v1.0.pdf"]],"v"],["aud","Allen & Heath Avantis 64-channel Digital Mixer","1","avantis","FOH console. <b>64 input channels, 24 faders over 6 layers</b>, two 15.6\" touchscreens, 12 XLR in / 12 XLR out on the surface, 100–240 V (150 W max), <b>57.4 lb (26 kg)</b>. Stage boxes connect through the expansion ports. <b>Phantom:</b> each socket shows when +48 V is on (indicated at +24 V). Allow time to boot before touching faders.",[["Avantis product page","www.allen-heath.com/hardware/avantis/avantis/"],["A&H downloads (guides, firmware)","www.allen-heath.com/resources/"]],"v"],["aud","Allen & Heath DX168 Stage Box","2","dx168","Stage box with mic inputs and outputs, linked to the console on <b>a single Cat5e STP cable up to 100 m on DX A</b>. <b>Stage box dead:</b> power, then the link cable and the DX A port. Look for the +48 V light on inputs.",[["DX168 getting started","support.allen-heath.com/hc/en-gb/articles/40432468352145-DX168-Getting-Started-Guide"]],"v"],["aud","RapcoHorizon Laptop Interface w/Ground Lift","4","rapco","Passive DI: takes a laptop's <b>3.5 mm stereo</b> line (6 ft hard-wired lead) and gives a <b>mono balanced mic-level XLR</b>. Needs no power. Has a <b>ground lift switch</b> and a <b>volume knob</b>. <b>Buzz or hum:</b> flip the ground lift. <b>Too quiet:</b> turn the knob up and raise the laptop volume.",[["Specs (B&H)","www.bhphotovideo.com/c/product/999455-REG/rapcohorizon_ltiglblox_blox_series_laptop.html/overview"]],"v"],["aud","Radial USB-PRO DI","2","radial","Stereo USB DI: plug the laptop into the USB-B port (no driver needed) and take <b>two balanced XLR outputs</b>. <b>Bus-powered</b> from USB (500 mA). Controls: <b>level, mono sum, isolation and ground lift</b>, plus a headphone output. <b>Hum or buzz:</b> engage isolation and ground lift. <b>No signal:</b> pick the USB-PRO as the laptop's audio output.",[["Specs and how to use (Markertek)","www.markertek.com/product/rad-usb-pro/radial-usb-pro-di-for-laptops-with-level-control-mono-summing-headphone-out"]],"v"],["aud","Shure ULXD Wireless Microphone System","6 systems","ulxd","Digital wireless in the <b>G50 band (470–534 MHz)</b>. Each system pairs a ULXD4 receiver with a ULXD1 bodypack and a ULXD2 handheld. Receiver RF light: <b>blue = good signal, red = interference, off = no signal</b>. Sync a transmitter to its receiver using the IR window.",[["Shure ULX-D guide (Spanish PDF)","pubs.shure.com/view/guide/ULXD/es-ES.pdf"]],"v"],["aud","Shure ULXD1 G50 Wireless Beltpack Transmitter","6","ulxd1","Bodypack transmitter for the WL185 lav. Fresh batteries before each show day. <b>No audio:</b> mute off, battery in, lav plugged in and screwed, and synced to the receiver (IR sync).",[["ULXD1 page","www.shure.com/en-US/products/wireless-systems/ulx-d_digital_wireless/ulxd1"]],"v"],["aud","Shure ULXD2 G50 Wireless Handheld Microphone SM58","6","","Wireless handheld with an SM58 capsule. Same G50 band and IR-sync routine as the bodypack. Check the battery and that the mute switch isn't engaged.",[["Shure ULX-D guide (Spanish PDF)","pubs.shure.com/view/guide/ULXD/es-ES.pdf"]],"v"],["aud","Shure ULXD4 G50 Single Channel Wireless Receiver","6","ulxd4","Single-channel receiver, rack mounted. Antennas out and clear; RF light shows signal state (blue good, red interference, off no signal). <b>Every mic drops:</b> check antennas and that the receiver's group/channel hasn't changed.",[["ULXD4 page","www.shure.com/en-US/products/wireless-systems/ulx-d_digital_wireless/ulxd4"]],"v"],["aud","Shure WL185 Lavalier Microphone","6","wl185","Small cardioid lavalier that plugs into the ULXD1. Clip about 6–8 inches under the chin, clear of jewelry and clothing that rubs. If it sounds muffled or scratchy, check the clip position first.",[["WL185 page","www.shure.com/en-US/products/microphones/wl185"]],"c"],["aud","Shure SM58 Wired Vocal Microphone","4","sm58","Dynamic cardioid vocal mic, <b>no phantom power needed</b>. Aim the front of the grille at the mouth and the rear (null) at the monitors to cut feedback. <b>Dead:</b> cable first, then the channel on the console.",[["SM58 page","www.shure.com/en-US/products/microphones/sm58"]],"c"],["aud","Pyle Tabletop Mic Stand","4","","Desk stand for wired mics. Check the clip holds the mic and that the base isn't pushing the cable out of the connector.",[],"c"],["aud","Misc Tall Boom Mic Stand Tripod","1","","Tripod boom stand. Spread the legs fully and point one leg under the boom's direction for stability.",[],"c"],["aud","XLR Cable Trunk","1","","Trunk of XLR cables. Cable totals are on the Cables tab: 30× 10', 50× 25', 260× 50', 60× 100'. Coil over-under and keep ends together.",[],"c"],["aud","SDI Video Trunk","1","","Trunk of SDI cable and barrels (SDI: 20× 50', 40× 100'; barrels 20×). Keep dust caps on.",[],"c"],["aud","Power Trunk","1","","Trunk of power cable. Edison counts are on the Cables tab. Check for damaged connectors before plugging in.",[],"c"],["com","Clear-Com FreeSpeak II Digital Wireless, 5 Channel System","2 systems","fsbase","Wireless digital intercom. Up to <b>20 beltpacks per base station, 5 per antenna</b>. <b>Registering a beltpack:</b> on the base station press <b>Menu → System → Reg → Start</b>, then on the beltpack choose <b>System Connect</b>. Default PIN is <b>0000</b>. The sheet says '5 Channel' but doesn't say which band (1.9 GHz or 2.4 GHz).",[["FreeSpeak II base station guide","clearcom.com/DownloadCenter/manuals/FreeSpeakII_v1.0/FreeSpeak_II_BaseStation_User-Guide-399G087C.pdf"]],"v"],["com","FreeSpeak II beltpack","(in the system)","fsbp","Wireless beltpack that registers to a base station. If it won't connect: confirm it is registered to that base (Menu → System → Reg → Start on the base; System Connect on the pack) and charged.",[["FreeSpeak II base station guide","clearcom.com/DownloadCenter/manuals/FreeSpeakII_v1.0/FreeSpeak_II_BaseStation_User-Guide-399G087C.pdf"]],"v"],["com","Clear-Com 2 Channel 5 Station Intercom System","1","","A wired Partyline system: a CS-702 main station powering RS-601 beltpacks and CC-95 headsets over mic cable. Two channels (A and B). If one beltpack is dead, swap its headset and cable first.",[["CS-702 details (Markertek)","markertek.com/product/cc-cs702/clear-com-cs-702-2-channel-portable-headset-main-station"]],"c"],["com","Clear-Com CS-702 2-Channel Portable Main Station","1","cs702","Two-channel Partyline main station (discontinued). <b>Built-in power supply (30 V DC per channel, 100–240 V mains)</b>, supports up to <b>55 beltpacks</b> on the two channels. Each channel has a <b>Call</b> button, Talk button, listen level and sidetone. A <b>Channel A &amp; B Link</b> switch makes it one channel. A <b>Remote Mic Kill</b> button turns off all beltpack mics. Short circuits reset when the fault is cleared.",[["CS-702 details (Markertek)","markertek.com/product/cc-cs702/clear-com-cs-702-2-channel-portable-headset-main-station"]],"v"],["com","Clear-Com RS 601 Beltpack","5","rs601","Single-channel Partyline beltpack, <b>4-pin headset</b>. Plug it into the Partyline cable, plug in the headset, and its Talk button latches or presses. <b>Nobody can hear you:</b> check headset plug, then the main station's channel assignment.",[["RS-601 beltpack info","clear-com.atlassian.net/wiki/spaces/SF/pages/158849106/Partyline+Single+channel+Beltpack"]],"v"],["com","Clear-Com CC-95 Single-Ear Intercom Headset","5","","Standard single-muff intercom headset (discontinued) with a <b>4-pin female XLR</b>. Plug into the beltpack's headset jack. <b>One-way audio:</b> try a known-good headset before blaming the pack.",[["CC-95 info","clear-com.atlassian.net/wiki/spaces/SF/pages/158713258/Partyline+What+is+the+CC-95"]],"v"],["rig","Motion Labs 3 Phase 200A, 9 Hole","1","","200 A 3-phase distribution with cam-lok feeder. <b>Hook-up starts at the ground end of the panel: GROUND (green) first, NEUTRAL (white) second, then the hot legs in the order they sit on that distro, working away from ground.</b> <b>Strike goes back toward the ground:</b> hot leg farthest from ground first, neutral second to last, <b>ground LAST</b>. Panels differ on which side ground is on, so read the panel.",[],"c"],["rig","Screw Pin Anchor Shackle 5/8 USA 4 1/2 Ton","4","","Rigging shackle. <b>The sheet lists a 5/8\" shackle at 4½ ton — check this with the rigger.</b> Always seat the pin fully, with the pin shoulder against the body, and never use bent or mismatched pins.",[],"c"],["rig","Steel Spanset 6'","2","","Steel wire rope sling (spanset) for hanging. Inspect for broken wires, kinks and crushing before every use, and keep it away from sharp edges.",[],"c"],["rig","Velour Performance Drape per foot 16' Single Panel Tall, Black","100 ft","","Black velour, 16 ft tall, sold per foot (100 ft). Pipe-and-drape (16' P/D, 150 ft on the sheet) holds it. Keep flame-retardant tags with the drape and keep it off hot fixtures.",[],"c"],["rig","16' P/D","150","","16-foot pipe and drape: uprights, base, pipe and drape together. Uprights fully locked, bases weighted.",[],"c"],["rig","2 powered exit signs","2","","Powered exit signs: keep clear of the line of sight and keep the power plugged in so the sign stays lit.",[],"c"],["rig","15'x25' Custom Printed AV Drop Center piece","1","","Printed drop for the stage centre. Handle by the edges, hang by the grommets or ties, and don't tape the printed face.",[],"c"],["rig","Expendables, Small Venue (Batteries/Tape/Misc..)","1","","Consumables kit: batteries, tape and miscellaneous. Check stock before doors, especially wireless mic and beltpack batteries.",[],"c"],["brk","Roland V160 / V-160HD","3 rooms","v160","The sheet lists 'Roland v160' in Concourse 150-151 and Petree C and D. Probably the V-160HD video switcher: <b>inputs 8 HDMI + 8 SDI; OUT 1 = Program, OUT 2 = Preview, OUT 3 = Multi-view</b>. PGM/A bus is the live output (lit red), PST/B is next (lit green). <b>CUT</b> switches instantly, <b>AUTO</b> uses the transition. Power: sources on first, then outputs, then the V-160HD last. Power off in reverse.",[["V-160HD quick start","shop.ccisolutions.com/StoreFront/jsp/pdf/RND-V-160HD_quickStart.pdf"],["Product page","proav.roland.com/global/products/v-160hd/"]],"v"],["brk","Shure MX412 Podium / Table Mic","most rooms","mx412","12\" cardioid gooseneck. <b>Phantom power only (11–52 V)</b> on a 3-pin XLR; no on/off switch and no light on the standard model. If all MX412 mics are dead but the wireless mics work, phantom is off on the mixer.",[["MX412 specs","www.bhphotovideo.com/c/product/127149-REG/Shure_MX412_C_MX412C_12_Cardioid.html"]],"v"],["brk","3k / 6k / 8k / 10k Short Throw Projector","all rooms","","Brightness classes: 3k small rooms, 6k large EDU and Concourse, 8k Petree, 10k Theater 411. The sheet doesn't give brand or model. <b>No picture:</b> lens cover, A/V mute, input source, HDMI at both ends, DA 1×4 power. Let the fan finish before pulling power. Brand and model are not on the sheet. General practice only; read the label on site.",[],"c"],["brk","7' / 8' Tripod Screen w/Skirt","most rooms","","Portable screen on a tripod. Pull the screen up fully, lock it with the support rod, and keep the skirt tidy. Square the projector to it.",[],"c"],["brk","7'x12' / 9'x16' FF Screen FP w/Skirt","big rooms","","Fast-fold front-projection screen: snap the frame, hook the surface, and check it is level before the projector goes on.",[],"c"],["brk","AV Cart / Projector Stand w/Skirt","most rooms","","Cart holds the projector (and laptop). Lock the casters, run cables to the side, and add the skirt.",[],"c"],["brk","40\" Confidence Monitor w/Stand","most rooms","","Presenter-facing monitor on a stand. Check the cable and the input.",[],"c"],["brk","Windows Laptop w/PPT","most rooms","","Windows laptop with PowerPoint for presenters. Check Win+P to extend or mirror, and set it to not sleep.",[],"c"],["brk","Laptop Audio DI","most rooms","","The room's laptop audio DI (see RapcoHorizon / Radial in Audio). If audio hums, flip the ground lift.",[],"c"],["brk","8\" / 12\" Powered Speaker w/Speaker Stand","most rooms","","Powered speakers on stands (8\" in most rooms, 12\" in Theater 411). Check mains power and the level knob, then the XLR in. Brand and model are not on the sheet. General practice only; read the label on site.",[],"c"],["brk","6 Channel / 12 Channel Audio Mixer","most rooms","","Small mixers for the room: 6 channels in most rooms, 12 channels in Concourse and Petree. Check phantom on for MX412 mics and the main fader up. Brand and model are not on the sheet. General practice only; read the label on site.",[],"c"],["brk","HDMI DA 1x4 / 1x8","most rooms","","HDMI distribution amplifier: one HDMI in, four (or eight) out. <b>Needs power</b>; a dead DA gives no picture on every display.",[],"c"],["brk","Wireless Combo RF Mic","some rooms","","Wireless mic with a combo kit. Fresh battery before use; check the mute switch. Brand and model are not on the sheet. General practice only; read the label on site.",[],"c"],["brk","Tritap","most rooms","","Tritap cable splits one power connector into three outlets. Don't overload it; know the circuit's amps.",[],"c"],["brk","6 Channel XLR Snake","some rooms","","100' or 150' 6-channel XLR snake used in Concourse and Petree rooms. Label the channels and keep the ends together.",[],"c"],["brk","Edison cable","—","","Edison (U-ground) extension cables: 25', 50' and 100' (counts on the Cables tab). Check for crushed plugs and damaged jackets.",[],"c"],["brk","Laser Printer / WiFi Access Point (Speaker Ready, Prod Office)","—","","Printers for Speaker Ready (308AB) and the CPG office (309), and a WiFi access point that <b>the sheet says still needs to be ordered</b>. Brand and model are not on the sheet. General practice only; read the label on site.",[],"c"],["brk","Monitors / TVs (South Lobby, Innovation Park, booths)","—","","32\" with brackets (South Lobby), 65\" TV on pole stand, and 12× 32\" wall-mount monitors at Innovation Park. Power, HDMI, input select. Brand and model are not on the sheet. General practice only; read the label on site.",[],"c"]];
var DEP=[["all","All","var(--txt)"],["vid","Video","var(--video)"],["lx","Lighting","var(--warn)"],["aud","Audio","var(--audio)"],["com","Comms","var(--sdi)"],["rig","Rig/Power","var(--power)"],["brk","Breakouts","var(--data)"]];
var cur="all",q="";
function photo(k){
 if(!k) return "";
 if(PH[k]) return "data:image/jpeg;base64,"+PH[k];
 var e=document.querySelector('img[data-k="'+k+'"]');
 return e?e.getAttribute("src"):"";
}
function col(d){for(var i=0;i<DEP.length;i++)if(DEP[i][0]===d)return DEP[i][2];return "var(--dim)";}
function lab(d){for(var i=0;i<DEP.length;i++)if(DEP[i][0]===d)return DEP[i][1];return d;}
function strip(h){return h.replace(/<[^>]+>/g," ");}
function render(){
 var out=document.getElementById("libOut"); if(!out) return;
 var n=0,html="";
 for(var i=0;i<GEAR.length;i++){
  var g=GEAR[i];
  if(cur!=="all" && g[0]!==cur) continue;
  if(q){var hay=(" "+g[1]+" "+strip(g[4])+" "+lab(g[0])).toLowerCase(),ok=true,ts=q.split(/\s+/);for(var t=0;t<ts.length;t++){if(ts[t]&&hay.indexOf(" "+ts[t])<0&&hay.indexOf("("+ts[t])<0&&hay.indexOf("\""+ts[t])<0){ok=false;break;}}if(!ok) continue;}
  n++;
  var src=photo(g[3]);
  html+='<div class="libcard" style="border-left-color:'+col(g[0])+'">'
   +(src?'<img class="libimg" loading="lazy" src="'+src+'" alt="'+g[1].replace(/"/g,"&quot;")+'">':'')
   +'<div class="libtxt"><div class="libhead"><b>'+g[1]+'</b><span class="libqty">'+g[2]+'</span></div>'
   +'<div class="libdept" style="color:'+col(g[0])+'">'+lab(g[0])+(g[6]==="c"?' &middot; <span class="pill p-rf">check</span>':' &middot; <span class="verified">from manual</span>')+'</div>'
   +'<p>'+g[4]+'</p>';
  for(var j=0;j<g[5].length;j++) html+='<a class="mfr" href="'+S+g[5][j][1]+'" target="_blank" rel="noopener">'+g[5][j][0]+' &#8599;</a>';
  if(src) html+='<div class="libcred">Photo &copy; manufacturer or retailer. Not my photo.</div>';
  html+='</div></div>';
 }
 document.getElementById("libCount").textContent=n+" of "+GEAR.length+" items";
 out.innerHTML=html||'<p class="lede">Nothing matches. Try the brand or the sheet wording.</p>';
}
var chips=document.getElementById("libChips");
if(chips){
 var ch="";
 for(var i=0;i<DEP.length;i++) ch+='<button class="btn libchip'+(i===0?" on":"")+'" data-d="'+DEP[i][0]+'">'+DEP[i][1]+'</button>';
 chips.innerHTML=ch;
 chips.addEventListener("click",function(e){
  var t=e.target; if(!t.getAttribute||!t.getAttribute("data-d")) return;
  cur=t.getAttribute("data-d");
  var all=chips.querySelectorAll(".libchip"); for(var i=0;i<all.length;i++) all[i].classList.toggle("on",all[i]===t);
  render();
 });
}
var inp=document.getElementById("libQ");
if(inp) inp.addEventListener("input",function(){q=inp.value.trim().toLowerCase();render();});
render();
})();
